    let entriesSeenByAfterSession: SessionEntry[] | undefined;

    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        throw new Error('beforeSession failed');
      },
      onError: async () => {},
      afterSession: async session => {
        entriesSeenByAfterSession = [...session.entries];
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('hi'), promptBuilder, undefined, {hooks});
